// Load governance prompt + compliance-screening skill
const input = $input.first().json;
const context = {
  system_prompt: '{{ governance prompt }}',
  skill: '{{ compliance-screening skill }}',
  content_to_review: input.content_to_review || {},
  target_market: input.target_market || {},
  query_id: input.query_id
};
return { json: context };

// Validate against governance-output schema
const response = $input.first().json;
const content = response.content?.[0]?.text || response.content || '{}';
let output;
try {
  output = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  output = { query_id: $json.query_id, error: 'Invalid JSON output' };
}
return { json: output };

// Check for critical flags and set flag_for_hitl if needed
const output = $input.first().json;
const hasCritical = (output.compliance_report?.egm_ai_policy_redlines_violations?.length > 0) ||
                    (output.compliance_report?.overall_status === 'non_compliant');
output.flag_for_hitl = hasCritical;
output.agent_name = 'governance';
output.model_used = 'claude-3-5-sonnet-20241022';
return { json: output };
